QFont FontPropertyGroup::toQFont() const
{
    QFont result;

    result.setFamily(d->family.value_or(QGuiApplication::font().family()));

    // TODO This needs a type with a proper unit so we can
    // distinguish pixel and point size.
    if (d->size) {
        result.setPixelSize(d->size.value());
    }

    result.setWeight(d->weight.value_or(QFont::Normal));
    result.setStyle(d->style.value_or(QFont::StyleNormal));
    result.setStretch(d->stretch.value_or(0));
    result.setCapitalization(d->capitalization.value_or(QFont::MixedCase));

    if (d->decorations) {
        if (d->decorations.value().testFlag(Union::Properties::TextDecoration::Underline)) {
            result.setUnderline(true);
        }

        if (d->decorations.value().testFlag(Union::Properties::TextDecoration::Overline)) {
            result.setOverline(true);
        }

        if (d->decorations.value().testFlag(Union::Properties::TextDecoration::StrikeThrough)) {
            result.setStrikeOut(true);
        }
    }

    result.setLetterSpacing(QFont::AbsoluteSpacing, d->letterSpacing.value_or(0.0));
    result.setWordSpacing(d->wordSpacing.value_or(0.0));

    return result;
}

